{
  "sword": { "damage": 12, "cooldown": 0.4, "knockback": 3 },
  "axe":   { "damage": 22, "cooldown": 0.9, "knockback": 6 },
  "spear": { "damage": 15, "cooldown": 0.6, "knockback": 2 }
}
// 실행 중 다시 불러오게(핫 리로드) → 재빌드 없이 조정 (분→초)
// 표로 빼면 비교 가능. 도끼가 정말 센 게 맞나를 눈으로 확인
// 비개발자(기획자)도 스프레드시트로 조정, 변경 이력 버전 관리

const dps = (w) => w.damage / w.cooldown;
// sword 30, axe 24.4 → 도끼는 한 방이 세지만 지속 피해는 낮다(검이 위)

const ehp = (unit) => unit.hp / (1 - unit.armor);   // 유효 체력(방어 감안)

// 원시 수치가 아니라 실제로 중요한 지표로 비교:
//   무기 = DPS, 유효 딜, 방어구 = 유효 체력, 진행 = 시간당 성장
// 파생값을 표로 계산, 출력하면 의도와 다른 항목이 드러난다

// 손으로 100줄 적지 말고 식으로 (파라미터 하나로 전체 조정)
const xpForLevel = (l) => Math.floor(100 * Math.pow(1.15, l));   // 지수
// 선형:  base + k * l         (꾸준함)
// 지수:  base * r^l           (후반 폭발. 과하면 인플레)
// 로그:  base * sqrt(l)       (초반 급성장 후 완만)

// 그 식이 몇 시간짜리 진행인지 계산, 시뮬로 확인 (math-prob)
const hoursToMax = simulate(xpForLevel, xpPerHour);   // 의도한 시간과 맞추기
